#!/usr/bin/env python3
"""Apply the Galaxy A51 (SM-A515F, Exynos 9611) hardware layer to an
A5XELTE-patched xnu tree (tools/dreamlte/prep-xnu-tree.sh output).

Two ways to get the same result:
  * this script, for a working tree with no git available: it runs the proven
    dreamlte layer first (that is what turns every hard-coded A5XELTE constant
    into an A5_* macro and brings in the Exynos UFS quirks), then re-points the
    board block at the A51;
  * xnu/patches/0125-a51-exynos9611.patch, generated by tools/a51/mkpatch0125.py
    from exactly the same board description (tools/a51/a51_board.py), for the
    patch pipeline / CI.

All board values are measured on hardware by shim/a51 and recorded in
A51_PROGRESS.md; see a51_board.py for the per-value provenance.

Usage: apply-a51.py XNU_TREE [--skip-stage1] [--keep-dreamlte]
"""
import subprocess
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
sys.path.insert(0, str(HERE))
import a51_board as B

DREAMLTE_APPLY = HERE.parent / 'dreamlte' / 'apply-dreamlte.py'

tree = Path(sys.argv[1]).resolve()
skip_stage1 = '--skip-stage1' in sys.argv
keep_dreamlte = '--keep-dreamlte' in sys.argv

hdr = tree / B.HEADER_REL
ufs = tree / B.UFS_REL
if not hdr.exists():
    raise SystemExit(f'{tree} is not an A5XELTE-patched xnu tree '
                     f'({B.HEADER_REL} missing); run '
                     'tools/dreamlte/prep-xnu-tree.sh first')

if not skip_stage1:
    print(f'== stage 1: {DREAMLTE_APPLY.name} on {tree}')
    subprocess.run([sys.executable, str(DREAMLTE_APPLY), str(tree)], check=True)

print('== stage 2: A51 board layer')
text = hdr.read_text()
if keep_dreamlte:
    # Only useful for inspecting the diff this script would produce.
    print(f'  --keep-dreamlte: leaving {B.HEADER_REL} untouched')
else:
    hdr.write_text(B.transformed_header(text))
    print(f'  edited {B.HEADER_REL}')

if ufs.exists():
    ufs.write_text(B.transformed_ufs(ufs.read_text()))
    print(f'  edited {B.UFS_REL}')
else:
    print(f'  WARNING: {B.UFS_REL} not present, UFS node name not updated')

print('\nA51 board facts now in the tree:')
for line in B.A51_HEADER_BLOCK:
    if line.startswith('#define') or line.startswith('#undef'):
        print('  ' + line)
